104	Avg-LogProb & 0.765 & [0.616, 0.820] & 0.204 \\
105	LD-Score & 0.721 & [0.588, 0.770] & 0.182 \\
106	FastDetectGPT & 0.627 & [0.511, 0.762] & 0.251 \\
107	Binoculars & 0.579 & [0.405, 0.664] & 0.259 \\
108	\bottomrule
109	\end{tabular}
